// Lays out the figures the API calculated. Nothing is computed here.
const pct = (r) => (r.value === null ? 'n/a' : r.value.toFixed(1) + '%') + ' (' + r.numerator + ' of ' + r.denominator + ' average headcount)';
const out = [];
for (const o of $input.first().json.organizations || []) {
  const rows = [
    ['Headcount at month end', o.closingHeadcount + ' (was ' + o.openingHeadcount + ')'],
    ['Joiners', o.joiners],
    ['Leavers', o.leavers],
    ['Turnover this month', pct(o.turnover.total)],
    ['Voluntary', pct(o.turnover.voluntary)],
    ['Involuntary', pct(o.turnover.involuntary)],
    ['Turnover, last 12 months', pct(o.rolling12Months.total)],
    ['Resignations awaiting approval', o.separationsAwaitingApproval],
    ['Employees serving notice', o.employeesServingNotice],
    ['Open clearance items', o.openClearanceItems + ' (' + o.overdueClearanceItems + ' overdue)'],
  ].map(([k, v]) => '<tr><td>' + k + '</td><td><b>' + v + '</b></td></tr>').join('');
  const notes = o.warnings.length ? '<p>Notes: ' + o.warnings.join(', ').replace(/_/g, ' ') + '.</p>' : '';
  for (const r of o.recipients) out.push({ json: { email: r.email, name: r.name, organization: o.organizationName, month: o.month, rows, notes, link: o.link } });
}
return out;
